create table if not exists public.sabily_families(id uuid primary key default gen_random_uuid(),owner_user_id uuid not null references auth.users(id) on delete cascade,family_name text not null,created_at timestamptz not null default now());
create table if not exists public.sabily_family_members(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.sabily_families(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,display_name text not null,relationship text not null default 'child' check(relationship in ('parent','child','guardian','adult_member')),birth_year integer,age_band text not null default 'child' check(age_band in ('child','teen','adult','senior')),avatar_key text,is_managed_profile boolean not null default true,created_at timestamptz not null default now(),unique(family_id,user_id));
alter table public.sabily_families enable row level security; alter table public.sabily_family_members enable row level security;
create policy "Family owners manage family" on public.sabily_families for all to authenticated using(owner_user_id=(select auth.uid())) with check(owner_user_id=(select auth.uid()));
create policy "Family owners manage member profiles" on public.sabily_family_members for all to authenticated using(exists(select 1 from public.sabily_families f where f.id=family_id and f.owner_user_id=(select auth.uid()))) with check(exists(select 1 from public.sabily_families f where f.id=family_id and f.owner_user_id=(select auth.uid())));
create index if not exists sabily_family_members_family_idx on public.sabily_family_members(family_id);
create table if not exists public.sabily_adhkar_items(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,category text not null check(category in ('morning','evening','after_prayer','before_sleep','upon_waking','daily','travel','general')),arabic_text text not null,transliteration text,translation text,repetitions integer not null default 1 check(repetitions between 1 and 1000),source_reference text not null,source_url text,sort_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now());
alter table public.sabily_adhkar_items enable row level security;
create policy "Authenticated users read active adhkar" on public.sabily_adhkar_items for select to authenticated using(active); grant select on public.sabily_adhkar_items to authenticated;
create table if not exists public.sabily_adhkar_progress(id bigint generated always as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,adhkar_id uuid not null references public.sabily_adhkar_items(id) on delete cascade,local_date date not null,completed_repetitions integer not null default 0 check(completed_repetitions>=0),completed_at timestamptz,unique(user_id,adhkar_id,local_date));
alter table public.sabily_adhkar_progress enable row level security;
create policy "Members manage own adhkar progress" on public.sabily_adhkar_progress for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create table if not exists public.sabily_adhkar_reminders(user_id uuid primary key references auth.users(id) on delete cascade,morning_enabled boolean not null default false,evening_enabled boolean not null default false,after_prayer_enabled boolean not null default false,hadith_enabled boolean not null default false,morning_time time not null default '07:00',evening_time time not null default '18:00',hadith_frequency text not null default 'daily' check(hadith_frequency in ('daily','weekly','off')),timezone text not null default 'Africa/Casablanca',enabled boolean not null default false,updated_at timestamptz not null default now());
alter table public.sabily_adhkar_reminders enable row level security;
create policy "Members manage own adhkar reminders" on public.sabily_adhkar_reminders for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create table if not exists public.sabily_growth_profiles(user_id uuid primary key references auth.users(id) on delete cascade,onboarding_version integer not null default 1,faith_goals text[] not null default '{}',learning_interests text[] not null default '{}',preferred_language text not null default 'en',experience_level text not null default 'beginner',daily_time_minutes integer not null default 10,reminder_style text not null default 'gentle',preferred_times jsonb not null default '{}'::jsonb,growth_plan jsonb not null default '[]'::jsonb,completed_at timestamptz,updated_at timestamptz not null default now());
alter table public.sabily_growth_profiles enable row level security;
create policy "Members manage own growth profile" on public.sabily_growth_profiles for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));